package com.smartexpense.data

import androidx.room.*

@Entity(tableName="accounts")
data class AccountEntity(@PrimaryKey val id:String, val name:String, val type:String, val archived:Boolean=false)
@Entity(tableName="walletSources",foreignKeys=[ForeignKey(entity=AccountEntity::class,parentColumns=["id"],childColumns=["walletId"]),ForeignKey(entity=AccountEntity::class,parentColumns=["id"],childColumns=["gpayId"])],indices=[Index("walletId"),Index("gpayId")])
data class WalletSourcesEntity(@PrimaryKey val id:Int=1,val walletId:String,val gpayId:String,val lastResetMonth:String)
@Entity(tableName="gpaySchedule")
data class GpayScheduleEntity(@PrimaryKey val id:Int=1,val enabled:Boolean=false,val target:Long=500000,val day:Int=1,val startMonth:String,val nextMonth:String)
@Entity(tableName="resetTargets",foreignKeys=[ForeignKey(entity=TransactionEntity::class,parentColumns=["id"],childColumns=["transactionId"],onDelete=ForeignKey.CASCADE)])
data class ResetTargetEntity(@PrimaryKey val transactionId:String,val target:Long)
@Entity(tableName="diary")
data class DiaryEntity(@PrimaryKey val date:String,val text:String)
@Entity(tableName="localPlans")
data class PlanEntity(@PrimaryKey val key:String,val kind:String,val json:String)
@Entity(tableName="receipts",foreignKeys=[ForeignKey(entity=TransactionEntity::class,parentColumns=["id"],childColumns=["transactionId"],onDelete=ForeignKey.CASCADE)])
data class ReceiptEntity(@PrimaryKey val transactionId:String,val mime:String,val text:String,val hash:String)
@Entity(tableName="receiptChunks",primaryKeys=["transactionId","position"],foreignKeys=[ForeignKey(entity=ReceiptEntity::class,parentColumns=["transactionId"],childColumns=["transactionId"],onDelete=ForeignKey.CASCADE)])
data class ReceiptChunkEntity(val transactionId:String,val position:Int,val bytes:ByteArray)
@Entity(tableName="localSettings")
data class LocalSettingsEntity(@PrimaryKey val id:Int=1,val name:String="",val avatar:String="initials",val welcomeDone:Boolean=false,val lastReviewMonth:String="")
@Entity(tableName="people")
data class PersonEntity(@PrimaryKey val id:String, val name:String, val aliases:String="")
@Entity(tableName="groups")
data class GroupEntity(@PrimaryKey val id:String, val name:String)
@Entity(tableName="members",primaryKeys=["groupId","personId"],foreignKeys=[ForeignKey(entity=GroupEntity::class,parentColumns=["id"],childColumns=["groupId"],onDelete=ForeignKey.CASCADE),ForeignKey(entity=PersonEntity::class,parentColumns=["id"],childColumns=["personId"])],indices=[Index("personId")])
data class GroupMemberEntity(val groupId:String,val personId:String)
@Entity(tableName="categories")
data class CategoryEntity(@PrimaryKey val id:String,val name:String,val color:Long=0xFFFFAB73,val icon:String="•",val archived:Boolean=false)
@Entity(tableName="transactions",foreignKeys=[ForeignKey(entity=CategoryEntity::class,parentColumns=["id"],childColumns=["categoryId"]),ForeignKey(entity=GroupEntity::class,parentColumns=["id"],childColumns=["groupId"])],indices=[Index("date"),Index("categoryId"),Index("groupId"),Index("kind")])
data class TransactionEntity(@PrimaryKey val id:String,val kind:String,val description:String,val amount:Long,val personalAmount:Long,val categoryId:String?,val groupId:String?,val date:Long,val notes:String,val reversed:Boolean=false,val refundOf:String?=null)
@Entity(tableName="entries",foreignKeys=[ForeignKey(entity=TransactionEntity::class,parentColumns=["id"],childColumns=["transactionId"]),ForeignKey(entity=AccountEntity::class,parentColumns=["id"],childColumns=["accountId"])],indices=[Index("transactionId"),Index("accountId")])
data class AccountEntryEntity(@PrimaryKey val id:String,val transactionId:String,val accountId:String,val amount:Long)
@Entity(tableName="shares",primaryKeys=["transactionId","personId"],foreignKeys=[ForeignKey(entity=TransactionEntity::class,parentColumns=["id"],childColumns=["transactionId"]),ForeignKey(entity=PersonEntity::class,parentColumns=["id"],childColumns=["personId"])],indices=[Index("personId")])
data class ShareEntity(val transactionId:String,val personId:String,val amount:Long)
@Entity(tableName="contributions",primaryKeys=["transactionId","personId"],foreignKeys=[ForeignKey(entity=TransactionEntity::class,parentColumns=["id"],childColumns=["transactionId"]),ForeignKey(entity=PersonEntity::class,parentColumns=["id"],childColumns=["personId"])],indices=[Index("personId")])
data class ContributionEntity(val transactionId:String,val personId:String,val amount:Long)
@Entity(tableName="obligations",foreignKeys=[ForeignKey(entity=TransactionEntity::class,parentColumns=["id"],childColumns=["transactionId"]),ForeignKey(entity=PersonEntity::class,parentColumns=["id"],childColumns=["fromPerson"]),ForeignKey(entity=PersonEntity::class,parentColumns=["id"],childColumns=["toPerson"])],indices=[Index("transactionId"),Index("fromPerson"),Index("toPerson")])
data class ObligationEntity(@PrimaryKey val id:String,val transactionId:String,val fromPerson:String,val toPerson:String,val amount:Long)
@Entity(tableName="settlements",foreignKeys=[ForeignKey(entity=TransactionEntity::class,parentColumns=["id"],childColumns=["transactionId"]),ForeignKey(entity=PersonEntity::class,parentColumns=["id"],childColumns=["fromPerson"]),ForeignKey(entity=PersonEntity::class,parentColumns=["id"],childColumns=["toPerson"])],indices=[Index(value=["transactionId"],unique=true),Index("fromPerson"),Index("toPerson")])
data class SettlementEntity(@PrimaryKey val id:String,val transactionId:String,val fromPerson:String,val toPerson:String,val amount:Long)
@Entity(tableName="allocations",primaryKeys=["settlementId","obligationId"],foreignKeys=[ForeignKey(entity=SettlementEntity::class,parentColumns=["id"],childColumns=["settlementId"]),ForeignKey(entity=ObligationEntity::class,parentColumns=["id"],childColumns=["obligationId"])],indices=[Index("obligationId")])
data class AllocationEntity(val settlementId:String,val obligationId:String,val amount:Long)
@Entity(tableName="budgets",foreignKeys=[ForeignKey(entity=CategoryEntity::class,parentColumns=["id"],childColumns=["categoryId"])],indices=[Index("categoryId")])
data class BudgetEntity(@PrimaryKey val id:String,val month:String,val categoryId:String?,val amount:Long)
@Entity(tableName="revisions",foreignKeys=[ForeignKey(entity=TransactionEntity::class,parentColumns=["id"],childColumns=["originalId"]),ForeignKey(entity=TransactionEntity::class,parentColumns=["id"],childColumns=["replacementId"])],indices=[Index("originalId"),Index("replacementId")])
data class RevisionEntity(@PrimaryKey val id:String,val originalId:String,val replacementId:String?,val date:Long,val reason:String)
data class AccountBalanceRow(val id:String,val name:String,val type:String,val archived:Boolean,val balance:Long)
data class DebtRow(val id:String,val transactionId:String,val fromPerson:String,val toPerson:String,val amount:Long,val outstanding:Long,val date:Long,val groupId:String?)
data class ReportTotalsRow(val spending:Long,val income:Long)
data class CategoryTotalRow(val categoryId:String?,val amount:Long)
data class DailyTotalRow(val day:String,val amount:Long)
data class GroupTotalRow(val groupId:String,val amount:Long)
